mapper.update:
UPDATE purchase_order_item
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = FALSE

mapper.select:
SELECT oi.sku_id, oi.sku_code_snapshot AS sku_code, oi.sku_name_snapshot AS sku_name, oi.product_name_snapshot AS product_name, oi.purchase_unit_snapshot AS purchase_unit, oi.product_type_snapshot AS product_type, COUNT(DISTINCT oi.purchase_order_id) AS order_count, COUNT(oi.id) AS line_count, SUM(oi.planned_quantity) AS planned_quantity, SUM(oi.received_quantity) AS received_quantity, SUM(GREATEST(oi.planned_quantity - oi.received_quantity, 0)) AS pending_quantity, SUM(GREATEST(oi.received_quantity - oi.planned_quantity, 0)) AS over_receipt_quantity FROM purchase_order_item oi JOIN purchase_order o ON o.id = oi.purchase_order_id AND o.deleted = FALSE WHERE oi.deleted = FALSE AND o.status IN ('SUBMITTED', 'PARTIALLY_RECEIVED')
AND o.supplier_id = #{query.supplierId}
AND o.warehouse_id = #{query.warehouseId}
AND o.order_no ILIKE CONCAT('%', #{query.orderNo}, '%')
AND (oi.product_name_snapshot ILIKE CONCAT('%', #{query.keyword}, '%') OR oi.sku_code_snapshot ILIKE CONCAT('%', #{query.keyword}, '%') OR oi.sku_name_snapshot ILIKE CONCAT('%', #{query.keyword}, '%'))
GROUP BY oi.sku_id, oi.purchase_unit_snapshot, oi.sku_code_snapshot, oi.sku_name_snapshot, oi.product_name_snapshot, oi.product_type_snapshot ORDER BY pending_quantity DESC NULLS LAST, oi.sku_id ASC
